base = sum(op[i]*(a[i]+1) for i in range(n))

# 计算后缀和数组，用于计算每个可能切割点的贡献
suffix = [0] * n
suffix[n-1] = op[n-1]
for i in range(n-2, -1, -1):
    suffix[i] = suffix[i+1] + op[i]

# 对于每个可能的切割点（位置 0 到 n-2），贡献为 suffix[i+1]
