for i in range(n-1):
    if suffix[i+1] > 0:
        contributions.append(suffix[i+1])

# 对贡献进行降序排序，选取最多 k-1 个
contributions.sort(reverse=True)
extra = sum(contributions[:max(0, k-1)])

# 输出最终答案
print(base + extra)
